 for(const [id,label]of [['editor','Bi\xEAn t\u1EADp ph\u1EE5 \u0111\u1EC1'],['dictation','Ch\xE9p ch\xEDnh t\u1EA3'],['speaking','Luy\u1EC7n n\xF3i'],['vocab','T\u1EEB v\u1EF1ng'],['data','D\u1EEF li\u1EC7u & \u0111\u1ED3ng b\u1ED9']])launch.append(button(label,()=>open(id)));
