 function switchTab(next){if(next!=='speaking')stopRecording();tab=next;for(const panel of dialog.querySelectorAll('.study-panel'))panel.hidden=panel.id!=='study-'+next;for(const b of dialog.querySelectorAll('[data-tab]'))b.setAttribute('aria-selected',String(b.dataset.tab===next));app.studyHideAnswers(next==='dictation');}
