 const versionId=()=> 'subtitle-'+uid();
 async function loadHistory(){const versions=lesson?(await store.all('subtitle')).filter(v=>v.lesson_id===lesson.lesson_id).sort((a,b)=>b.created_at.localeCompare(a.created_at)):[];$('edHistory').replaceChildren();for(const v of versions){const o=document.createElement('option');o.value=v.id;o.textContent=new Date(v.created_at).toLocaleString('vi')+(v.original?' \xB7 B\u1EA3n g\u1ED1c':'');$('edHistory').append(o);}$('edPublish').hidden=user.role!=='admin'||!lesson?.sharedSourceId;}
